// import React from "react";

function RatingStars({ value = 0, onChange = () => {}}) {

  const stars = Array.from({ length: max = 5}, (_, i) => i++);
  return (
    <div className="stars">
      {stars.map((n) => (
        <button type="button" role="radio" onClick={() => onChange(n)}>
          {n <= value ? "*" : "-"}
        </button>
      ))}
    </div>
  );
}

export default RatingStars;
